import{_ as s,r as t,o as n,c as o,e as i,a as l,s as u}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"Creating a Forum - October CMS User Guide","titleTemplate":false,"description":"Build a community forum with October CMS using the RainLab Forum and User plugins.","frontmatter":{"subtitle":"Build a community forum with October CMS using the RainLab Forum and User plugins."},"headers":[{"level":2,"title":"What You Will Build","slug":"what-you-will-build","link":"#what-you-will-build","children":[]},{"level":2,"title":"Plugins vs Tailor","slug":"plugins-vs-tailor","link":"#plugins-vs-tailor","children":[]},{"level":2,"title":"Prerequisites","slug":"prerequisites","link":"#prerequisites","children":[]},{"level":2,"title":"Overview","slug":"overview","link":"#overview","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/forum/introduction.md","filePath":"user-guide/forum/introduction.md"}'),h={name:"user-guide/forum/introduction.md"};function d(p,e,g,c,m,f){const a=t("pre-heading"),r=t("post-heading");return n(),o("div",null,[i(a),e[0]||(e[0]=l("h1",null,"Creating a Forum",-1)),i(r),e[1]||(e[1]=u('<p>In this tutorial, you will build a community forum using October CMS plugins. By the end, you will have user registration and login, discussion channels, topics with replies, and member profiles, all powered by plugins with no custom PHP.</p><h2 id="what-you-will-build"><a href="#what-you-will-build" class="header-anchor">#</a> What You Will Build</h2><p>You will create a forum powered by two plugins: RainLab.User for authentication and RainLab.Forum for discussions. The finished forum includes:</p><ul><li><strong>User registration and login</strong> with password reset</li><li><strong>Discussion channels</strong> for organizing topics by category</li><li><strong>Topics and posts</strong> where members can start discussions and reply</li><li><strong>Member profiles</strong> showing activity and post history</li><li><strong>Moderation tools</strong> for managing content and members</li></ul><h2 id="plugins-vs-tailor"><a href="#plugins-vs-tailor" class="header-anchor">#</a> Plugins vs Tailor</h2><p>In the <a href="./../blog/introduction.html">blog tutorial</a>, you defined content with YAML blueprints and wrote all the Twig markup yourself. Tailor gives you complete control over the data structure, but you build everything from scratch.</p><p>Plugins take a different approach. They are installable packages that bring their own database tables, backend management pages, and frontend components. You install them, configure their settings, and write your own templates to display the data they provide.</p><h2 id="prerequisites"><a href="#prerequisites" class="header-anchor">#</a> Prerequisites</h2><p>Before starting, you should have:</p><ul><li>October CMS installed and running</li><li>A theme with a default layout that includes Tailwind CSS</li></ul><p>If you haven&#39;t done this yet, work through the <a href="./../quickstart/editor/creating-a-layout.html">Quick Start guide</a> first. This tutorial assumes you have a working layout similar to the one created there.</p><h2 id="overview"><a href="#overview" class="header-anchor">#</a> Overview</h2><p>This tutorial is split into two parts:</p><p><strong>Part 1: User Authentication</strong></p><ol><li><a href="./installing-the-user-plugin.html">Installing the User Plugin</a>: install RainLab.User and configure your layout</li><li><a href="./login-and-registration.html">Login and Registration</a>: create login and registration pages</li><li><a href="./password-reset.html">Password Reset</a>: add a password reset flow</li></ol><p><strong>Part 2: The Forum</strong></p><ol start="4"><li><a href="./installing-the-forum-plugin.html">Installing the Forum Plugin</a>: install RainLab.Forum and create channels</li><li><a href="./forum-pages.html">Forum Pages</a>: build the forum index and channel pages</li><li><a href="./topic-page.html">Topic Page</a>: create topics, post replies, and moderate discussions</li><li><a href="./member-profile.html">Member Profile</a>: add member profiles with activity and moderation tools</li></ol><p>Part 1 covers user authentication as a self-contained guide. Future tutorials that need user accounts will reference these pages. Part 2 builds on Part 1 to create the forum itself.</p><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Continue to <a href="./installing-the-user-plugin.html">Installing the User Plugin</a> to get started with user authentication.</p>',20))])}const v=s(h,[["render",d]]);export{b as __pageData,v as default};
